<?php
header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
header('Pragma: no-cache');
header('X-Robots-Tag: noindex, nofollow, noarchive');
header('Referrer-Policy: same-origin');
require __DIR__.'/app/bootstrap.php';
$returnKey=login_return_key();$pwaMode=$returnKey==='time'||((string)($_GET['pwa']??''))==='1';
if($cu=current_user()){header('Location:'.login_success_target($cu,$returnKey));exit;}
$err='';$msg=isset($_GET['forgot'])?'ลืมอุปกรณ์นี้แล้ว กรุณาเข้าสู่ระบบใหม่':'';$d=db_load();$remembered=remembered_device($d);
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_check();$action=(string)($_POST['action']??'password');
 if($action==='forget_device'){
   forget_current_device();header('Location:login.php'.login_return_query($returnKey,['forgot'=>1]));exit;
 }
 if($action==='pin'){
   $result=pin_login(trim((string)($_POST['pin']??'')));
   if(!empty($result['ok'])){header('Location:'.login_success_target((array)$result['user'],$returnKey));exit;}
   $err=(string)$result['message'];$d=db_load();$remembered=remembered_device($d);
 }else{
   $username=trim((string)($_POST['username']??''));$u=null;
   foreach($d['users'] as $x)if(strtolower((string)$x['username'])===strtolower($username)&&!empty($x['active'])){$u=$x;break;}
   if($u&&password_verify((string)($_POST['password']??''),(string)$u['password_hash'])){
     establish_session($u);
     if(!empty($_POST['remember_device'])){$_SESSION['needs_pin_setup']=1;header('Location:setup-pin.php'.login_return_query($returnKey));exit;}
     header('Location:'.login_success_target($u,$returnKey));exit;
   }
   $err='ชื่อผู้ใช้หรือรหัสผ่านไม่ถูกต้อง';
 }
}
