<div class="card password-panel <?=$remembered?'':'show'?>" id="passwordCard"><div class="icon">⌾</div><div class="eyebrow"><?=$pwaMode?'MR BAR TIME ACCESS':'STAFF ACCESS'?></div><h2>เข้าสู่ระบบ</h2><p><?=$pwaMode?'สำหรับพนักงานทุกตำแหน่งที่มีบัญชี MR BAR TIME':'สำหรับ Admin / พนักงาน / PR'?></p><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="password"><?php if($returnKey!==''):?><input type="hidden" name="return_to" value="<?=h($returnKey)?>"><?php endif;?><div class="field"><label>USERNAME</label><input name="username" required autocomplete="username" autocapitalize="none" spellcheck="false" inputmode="text" placeholder="Username"></div><div class="field"><label>PASSWORD</label><input name="password" type="password" required autocomplete="current-password" placeholder="Password"></div><label class="remember"><input type="checkbox" name="remember_device" value="1" checked><span>จำอุปกรณ์นี้ และตั้ง PIN 6 หลักหลัง Login</span></label><button class="login-btn">LOGIN →</button></form><?php if($remembered):?><a class="back" href="#" onclick="showQuick();return false">← กลับไปใช้ PIN</a><?php elseif(!$pwaMode):?><a class="back" href="custumers/">← กลับไปหน้า Guest Check-in</a><?php else:?><div class="back">MR BAR TIME · SECURE STAFF ACCESS</div><?php endif;?></div></section></main><div class="version">● <?=h(app_config()['pack'])?> · <?=h(app_config()['version'])?></div><script>const pin=document.getElementById('pin');if(pin){pin.addEventListener('input',()=>{pin.value=pin.value.replace(/\D/g,'').slice(0,6);if(pin.value.length===6)setTimeout(()=>document.getElementById('pinForm').requestSubmit(),120)})}function showPassword(){document.getElementById('quickCard')?.classList.add('hide');document.getElementById('passwordCard')?.classList.add('show')}function showQuick(){document.getElementById('quickCard')?.classList.remove('hide');document.getElementById('passwordCard')?.classList.remove('show')}<